import {createChatOrchestrator} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';

it('includes the budget-ending provider call in turn usage @spec(specs/hal-engine-config-hooks/spec.md#13)', async () => {
  const rounds: UsageMetadata[] = [
    {inputTokens: 2, outputTokens: 3, totalTokens: 5},
    {inputTokens: 7, outputTokens: 11, totalTokens: 18},
  ];
  const provider: AIProvider = {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      yield {type: 'tool_use', toolCall: {id: 'lookup', name: 'lookup', input: {}}};
      yield {type: 'stop', stopReason: 'tool_use', usage: rounds.shift()};
    },
    async generateStructured<T>(): Promise<T> {
      throw new Error('Structured output is outside this contract');
    },
  };
  const registry = new ToolRegistry();
  registry.register({name: 'lookup', description: 'Lookup', inputSchema: {type: 'object'}}, async () => 'found');
  let reported: UsageMetadata | undefined;
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Usage contract'}), registry, {
    maxToolRounds: 1,
    hooks: {
      afterModelResponse: async (_session, _text, usage) => {
        reported = usage;
      },
    },
  });

  await orchestrator.processMessage({sessionId: 'usage', userId: 'user', entries: []});

  expect(reported).toEqual({inputTokens: 9, outputTokens: 14, totalTokens: 23});
});
EOF
timeout 300 npm test -- --runTestsByPath src/orchestration/turnUsage.contract.test.ts --runInBand"
